test('addLine and removeLine can be chained', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);

  const r2 = addLine(r.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);

  const r3 = addLine(r2.value, { sku: 'COPY-HOUR', qty: 2 });
  assert.equal(r3.ok, true);
  assert.equal(r3.value.lines.length, 3);

  const r4 = removeLine(r3.value, 'DEV-HOUR');
  assert.equal(r4.ok, true);
  assert.equal(r4.value.lines.length, 2);
  assert.equal(r4.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r4.value.lines[1].sku, 'COPY-HOUR');
});
